        // 支持通过 rowSelection.headerCell 来自定义“全选”列的表头渲染，
        // 如果没有传 headerCell，则仍旧使用默认的 renderSelectionHeader
        children.unshift(
            <Col
                key="selection"
                title={rowSelection.headerCell || this.renderSelectionHeader.bind(this)}
                cell={this.renderSelectionBody.bind(this)}
